/**
 * **The join/failure matrix — ladder L5, and the evidence ADR 0003 is written
 * from.**
 *
 * Every cell below was written by hand from `spec/join-policy.md` sections 2-4
 * before it was run. `doc/workflow.md` section 5: expected values come from the
 * spec, and a snapshot generated by running the implementation is not a test.
 * Concretely, each expectation is derivable with the document open and no code:
 *
 *   `arrival-count`  N is COUNTED from `branch.opened` — one per branch the region
 *                    opened (`spec/join-policy.md` v0.12); satisfied on N distinct
 *                    `branch.arrived` with N at least one; **every other event
 *                    ignored**; never `unsatisfiable`. *(This read
 *                    *"N = `region.branches.length`, fixed at `open`"* — the
 *                    pre-v0.12 source, left behind by
 *                    [W33](../../doc/work-items/w33-a-map-at-run-time-arity.md),
 *                    which changed the policy and every cell's derivation and not
 *                    this header. It is a map region where the two differ, and
 *                    there is no map row here, so no cell moved and nothing said
 *                    so — `doc/workflow.md` section 1 rule 5's *any copy,
 *                    including your own*.)*
 *   `live-token`     `branch.opened` +1; `arrived`/`exited`/`lost` -1;
 *                    `suspended`/`resumed` neither; satisfied at zero **having
 *                    been positive**; never `unsatisfiable`.
 *
 * **W4 does not repair either policy.** `JP-R7` and `JP-R8` say the one-line
 * improvements are third policies, and `variants.test.ts` is where that claim is
 * made falsifiable. A row where a policy behaves badly is the result.
 */
import { deepEqual, equal, ok, suite } from '../harness.ts';
import { arrivalCount, liveToken, POLICIES } from '../../src/fold/policies.ts';
import type { JoinPolicy, JsonValue } from '../../src/driver/policy.ts';
import { type Cell, runCell, type Verdict } from './run.ts';
import { mapRows, matrixRows, nestedRows, renderMap, renderMatrix, renderNested } from './table.ts';
import { MAP_SCENARIOS, NESTED_SCENARIOS, SCENARIOS } from './scenarios.ts';
import { allRegions, branchPathOf, buildGraph } from '../../src/definition/regions.ts';
import {
  MATRIX_COLUMNS,
  MATRIX_POLICY_IDS,
  PINNED_POLICY_IDS,
  SHIPPED_POLICY_IDS,
  VARIANT_POLICY_IDS,
} from './variants.ts';

interface Answer {
  status: string;
  describe: JsonValue;
  verdict: Verdict;
}

interface Expected {
  events: string[];
  ac: Answer;
  lt: Answer;
  /** `JP-R7`'s variant — `arrival-count` decrementing N on `branch.exited`. */
  acDec: Answer;
  /** `JP-R8`'s variant — `live-token` requiring an arrival before `satisfied`. */
  ltArr: Answer;
}

const waiting = (describe: JsonValue, verdict: Verdict) => ({ status: 'waiting', describe, verdict });
const satisfied = (describe: JsonValue) => ({ status: 'satisfied', describe, verdict: 'joined' as const });
/**
 * **The third status, and only the fourth column can produce it.**
 * `spec/join-policy.md` section 3 says neither shipped policy is ever
 * `unsatisfiable`; section 4 says the driver then **routes nowhere**, so the
 * verdict is `stuck` by construction rather than by coincidence.
 */
const unsatisfiable = (describe: JsonValue) =>
  ({ status: 'unsatisfiable', describe, verdict: 'stuck' as const });

/** `need`/`arrived` is arrival-count's `describe`; `live`/`positive` is live-token's. */
const ac = (need: number, arrived: string[]) => ({ need, arrived });
const lt = (live: number, positive = true) => ({ live, positive });
/**
 * The `JP-R8` variant's `describe`, which is `live-token`'s plus the counter its
 * one line reads. A different shape from `lt` above **is the evidence** that the
 * fourth column is a different policy rather than a re-run of the second.
 */
const ltA = (live: number, arrived: number, positive = true) => ({ live, positive, arrived });

const EXPECTED: Record<string, Expected> = {
  // The control row. If the two policies disagreed here the experiment would have
  // no baseline and every other row would be unreadable.
  'all-arrive': {
    events: ['opened(split:0)', 'opened(split:1)', 'arrived(split:0)', 'arrived(split:1)'],
    ac: satisfied(ac(2, ['0', '1'])),
    lt: satisfied(lt(0)),
    acDec: satisfied(ac(2, ['0', '1'])),
    ltArr: satisfied(ltA(0, 2)),
  },

  // **P1's case.** One branch reaches an `end` instead of the join. Arrival-count
  // is still waiting for a second arrival that can never come, and says so with
  // `waiting` rather than `unsatisfiable` — which is why the verdict, not the
  // status, is what reports the hang.
  'routed-away': {
    events: ['opened(split:0)', 'opened(split:1)', 'arrived(split:0)', 'exited(split:1)'],
    ac: waiting(ac(2, ['0']), 'stuck'),
    lt: satisfied(lt(0)),
    acDec: satisfied(ac(1, ['0'])),
    ltArr: satisfied(ltA(0, 1)),
  },

  'lost-settled': {
    events: ['opened(split:0)', 'opened(split:1)', 'arrived(split:0)', 'lost(split:1)'],
    ac: waiting(ac(2, ['0']), 'stuck'),
    lt: satisfied(lt(0)),
    acDec: waiting(ac(2, ['0']), 'stuck'),
    ltArr: satisfied(ltA(0, 1)),
  },

  // The same terminal event as `lost-settled`, reached by the other road: a human
  // resolving a suspended node `failed` (`RS-R3`). Two rows, one event — which is
  // section 2's claim, checked rather than restated.
  'lost-resolved': {
    events: ['opened(split:0)', 'opened(split:1)', 'arrived(split:0)', 'suspended(split:1)', 'resumed(split:1)', 'lost(split:1)'],
    ac: waiting(ac(2, ['0']), 'stuck'),
    lt: satisfied(lt(0)),
    acDec: waiting(ac(2, ['0']), 'stuck'),
    ltArr: satisfied(ltA(0, 1)),
  },

  // Q5's "optional branch resolving null". `state = 'failed'` and `resolve(null)`
  // are two lines of one branch upstream, so what reaches the flow is an ordinary
  // `failed` — and because this flow's optional node HAS an `on: ["failed"]` edge,
  // the branch exits rather than being lost. Indistinguishable from `routed-away`
  // at the policy, which is the point.
  'optional-null': {
    events: ['opened(split:0)', 'opened(split:1)', 'exited(split:0)', 'arrived(split:1)'],
    ac: waiting(ac(2, ['1']), 'stuck'),
    lt: satisfied(lt(0)),
    acDec: satisfied(ac(1, ['1'])),
    ltArr: satisfied(ltA(0, 1)),
  },

  // **The row that separates "waiting on a human" from "stuck".** Both policies
  // say `waiting` and both are RIGHT; a matrix that reported this as a hang would
  // be making the exact mistake ADR 0004 and `branch.suspended` exist to prevent.
  suspended: {
    events: ['opened(split:0)', 'opened(split:1)', 'arrived(split:0)', 'suspended(split:1)'],
    ac: waiting(ac(2, ['0']), 'waiting-on-human'),
    lt: waiting(lt(1), 'waiting-on-human'),
    acDec: waiting(ac(2, ['0']), 'waiting-on-human'),
    ltArr: waiting(ltA(1, 1), 'waiting-on-human'),
  },

  // Suspension is not terminal (ADR 0004 rule 4). Both policies agree again.
  resumed: {
    events: ['opened(split:0)', 'opened(split:1)', 'arrived(split:0)', 'suspended(split:1)', 'resumed(split:1)', 'arrived(split:1)'],
    ac: satisfied(ac(2, ['0', '1'])),
    lt: satisfied(lt(0)),
    acDec: satisfied(ac(2, ['0', '1'])),
    ltArr: satisfied(ltA(0, 2)),
  },

  // **The row `JP-R8` exists because of.** Nothing arrives at all. Live-token
  // fires a join no branch reached, carrying `null` downstream; arrival-count
  // waits forever on a count that started at two. Neither is obviously right, and
  // that is the finding rather than a tie.
  'all-exit': {
    events: ['opened(split:0)', 'opened(split:1)', 'exited(split:0)', 'suspended(split:1)', 'resumed(split:1)', 'exited(split:1)'],
    ac: waiting(ac(2, []), 'stuck'),
    lt: satisfied(lt(0)),
    acDec: satisfied(ac(0, [])),
    ltArr: unsatisfiable(ltA(0, 0)),
  },

  // `JP-R4`'s column: all six events in one stream, on three branches.
  'six-events': {
    events: [
      'opened(split:0)', 'opened(split:1)', 'opened(split:2)',
      'lost(split:0)', 'exited(split:1)', 'suspended(split:2)', 'resumed(split:2)', 'arrived(split:2)',
    ],
    ac: waiting(ac(3, ['2']), 'stuck'),
    lt: satisfied(lt(0)),
    acDec: waiting(ac(2, ['2']), 'stuck'),
    ltArr: satisfied(ltA(0, 1)),
  },
};

/**
 * **The four columns, in render order — imported, not rebuilt.**
 *
 * `MATRIX_POLICY_IDS` is the id list and `MATRIX_COLUMNS` is the policy list;
 * they are asserted to agree below, because two lists that must line up and are
 * never compared is how a column silently becomes a duplicate of its neighbour.
 * **`test/matrix/render.ts` prints from the same import**, which is what makes
 * that assertion cover the exit artifact and not just this file — it did not,
 * and W15's conformity reader is what found it.
 */
const COLUMNS = MATRIX_COLUMNS;

const cellsFor = (key: string) => {
  const scenario = SCENARIOS.find((s) => s.key === key)!;
  return { scenario, cells: COLUMNS.map((p) => runCell(scenario, p)) };
};
const ALL = SCENARIOS.map((s) => cellsFor(s.key));

/**
 * The depth-2 rows, run the same way — W22's four against the same four columns.
 * **A separate binding rather than four more entries in `ALL`**, for the reason
 * `scenarios.ts` gives for keeping them out of `SCENARIOS`: the nine are Q5's
 * cases and ADR 0003 counts them. `JP-R12`'s assertions run over BOTH, because a
 * nested region is where its key-order clause has its only live case.
 */
const NESTED_ALL = NESTED_SCENARIOS.map((scenario) => ({
  scenario,
  cells: COLUMNS.map((p) => runCell(scenario, p)),
}));

/**
 * **The map rows — L5 at a RUN-TIME arity.** A third list for the same reason
 * `NESTED_ALL` is a second one: the nine are Q5's cases and ADR 0003 counts them,
 * and a region's WIDTH is a different axis from a branch's fate.
 */
const MAP_ALL = MAP_SCENARIOS.map((scenario) => ({
  scenario,
  cells: COLUMNS.map((p) => runCell(scenario, p)),
}));

/**
 * **By id, never by index.** With two columns `cells[0]`/`cells[1]` was legible;
 * with four it is a positional dependency between this file, `COLUMNS` and
 * `variants.ts`, and reordering the list would silently swap two policies'
 * expectations rather than failing.
 */
const cellOf = (row: { cells: Cell[] }, policyId: string): Cell =>
  row.cells.find((c) => c.policyId === policyId)!;

/** Every cell as `row/policy` -> cell, for the whole-matrix assertions. */
const BY_KEY = new Map(ALL.flatMap(({ scenario, cells }) =>
  cells.map((c) => [`${scenario.key}/${c.policyId}`, c] as const)));

suite('L5 — the join/failure matrix, cell by cell', (test) => {
  for (const scenario of SCENARIOS) {
    const want = EXPECTED[scenario.key]!;
    const row = ALL.find((r) => r.scenario.key === scenario.key)!;
    const got = cellOf(row, 'arrival-count');
    const gotLt = cellOf(row, 'live-token');
    const gotAcDec = cellOf(row, 'arrival-count-decrementing');
    const gotLtArr = cellOf(row, 'live-token-requiring-arrival');

    test(`${scenario.key}: the region event stream is what the driver emits`, () => {
      equal(got.events, want.events,
        `${scenario.key}: the stream is the policy's whole input, so a wrong stream makes every ` +
        'other assertion in this row meaningless');
      for (const other of [gotLt, gotAcDec, gotLtArr]) {
        equal(other.events, want.events,
          `and it is IDENTICAL under ${other.policyId}. A policy cannot change what the driver ` +
          'emits, so all four columns are compared on the same input — without that the matrix ' +
          'is not an experiment, it is four runs');
      }
    });

    test(`${scenario.key}: arrival-count`, () => {
      equal({ status: got.status, describe: got.describe, verdict: got.verdict }, want.ac,
        `${scenario.key} under arrival-count — expected from spec/join-policy.md section 3: ` +
        'N fixed at open, satisfied on N distinct arrivals, every other event ignored');
      equal(got.joinFired, want.ac.status === 'satisfied',
        'and what it SAID matches what the driver DID. A detector that disagrees with the ' +
        'behaviour is worse than none, because Q7 is about trusting exactly this report');
    });

    test(`${scenario.key}: live-token`, () => {
      equal({ status: gotLt.status, describe: gotLt.describe, verdict: gotLt.verdict }, want.lt,
        `${scenario.key} under live-token — expected from spec/join-policy.md section 3: ` +
        'opened +1, arrived/exited/lost -1, suspended/resumed neither, satisfied at zero ' +
        'having been positive');
      equal(gotLt.joinFired, want.lt.status === 'satisfied',
        'and what it said matches what the driver did');
    });

    test(`${scenario.key}: arrival-count-decrementing (JP-R7)`, () => {
      // Section 3 plus the one line `JP-R7` names: N starts at
      // `region.branches.length` and **`branch.exited` decrements it**. Nothing
      // else changes, so `branch.lost` still never moves N — which is why this
      // column is a third policy rather than a repair.
      equal({ status: gotAcDec.status, describe: gotAcDec.describe, verdict: gotAcDec.verdict }, want.acDec,
        `${scenario.key} under arrival-count-decrementing — expected from spec/join-policy.md ` +
        "section 3's arrival-count, with N decremented on branch.exited and on nothing else");
      equal(gotAcDec.joinFired, want.acDec.status === 'satisfied',
        'and what it said matches what the driver did');
    });

    test(`${scenario.key}: live-token-requiring-arrival (JP-R8)`, () => {
      // Section 3's `live-token`, plus the clause v0.1 of the spec shipped:
      // `satisfied` only if a branch actually arrived, and **`unsatisfiable`
      // otherwise**. Section 4 then fixes what the driver does with that answer —
      // report and route nowhere — so `joinFired` is asserted against `satisfied`
      // and not against "not waiting".
      equal({ status: gotLtArr.status, describe: gotLtArr.describe, verdict: gotLtArr.verdict }, want.ltArr,
        `${scenario.key} under live-token-requiring-arrival — expected from ` +
        "spec/join-policy.md section 3's live-token, plus JP-R8's arrival requirement");
      equal(gotLtArr.joinFired, want.ltArr.status === 'satisfied',
        'and what it said matches what the driver did — an `unsatisfiable` join must route ' +
        'NOWHERE (section 4), which reading only `.status` would not catch');
    });
  }
});

suite('L5 — what the matrix says as a whole', (test) => {
  test('JP-R3: every cell answers one of three, and no cell is blank', () => {
    equal(BY_KEY.size, SCENARIOS.length * MATRIX_POLICY_IDS.length,
      'nine rows times four columns. An inexact count here would let a column go missing and ' +
      'the loop below still report every cell it was given as fine');
    for (const { scenario, cells } of ALL) {
      for (const c of cells) {
        ok(['waiting', 'satisfied', 'unsatisfiable'].includes(c.status),
          `${scenario.key}/${c.policyId}: "${c.status}" is not a status. A blank cell is a spec ` +
          'hole with an address (spec/join-policy.md, JP-R3)');
      }
    }
  });

  test('JP-R4: every one of the six events is exercised, and one row carries all six', () => {
    const everywhere = new Set(ALL.flatMap(({ cells }) => cells[0]!.events.map((e) => e.split('(')[0])));
    equal([...everywhere].sort(), ['arrived', 'exited', 'lost', 'opened', 'resumed', 'suspended'],
      'the vocabulary is sized for the richer policy, and a matrix that never drove an event ' +
      'would let the driver stop emitting it without anything noticing — which for ' +
      'branch.exited would decide Q4 by omission');
    const six = ALL.find((r) => r.scenario.key === 'six-events')!.cells[0]!;
    equal(new Set(six.events.map((e) => e.split('(')[0])).size, 6,
      'and JP-R4 asks for a COLUMN that exercises every event, not six columns that between ' +
      'them do — an interleaving is a different input from six separate streams');
  });

  test('neither SHIPPED policy ever returns unsatisfiable, on any row', () => {
    // `spec/join-policy.md` section 4 calls this a result rather than a gap: P1
    // ships with no policy that can say "this join can never fire". Nine rows,
    // two shipped policies, and the value never appears — so a stuck join is
    // detected by quiescence or not at all, which is precisely the pressure Q7
    // describes.
    //
    // **W15 narrowed this to the shipped pair and it is the one assertion the
    // fourth column could have silently weakened.** Left reading `cells`, adding
    // a column that CAN say `unsatisfiable` would have turned a claim about the
    // two policies section 3 names into a false claim about four — and it would
    // have gone red, which is how the narrowing was noticed rather than assumed.
    //
    // **W16 re-narrowed it from SHIPPED to PINNED, and it went red first.** ADR
    // 0025 ships a third policy that says `unsatisfiable`, so *"the shipped
    // policies never say it"* became false the moment `POLICIES` grew — while the
    // sentence this assertion is FOR, section 3's pin on the two W4 compared, did
    // not change at all. Two ideas had been sharing one list.
    const seen = new Set(ALL.flatMap(({ cells }) =>
      cells.filter((c) => PINNED_POLICY_IDS.includes(c.policyId)).map((c) => c.status)));
    equal([...seen].sort(), ['satisfied', 'waiting'],
      'if `unsatisfiable` ever appeared here, one of the two PINNED policies had been quietly ' +
      'refined past its section 3 definition (JP-R7, JP-R8) — which is exactly what ADR 0025 ' +
      'did NOT do: it built JP-R8`s refinement beside live-token rather than inside it');
  });

  test('and exactly one cell in the whole matrix says it', () => {
    // The other half of the same fact, and the reason the fourth column is worth
    // rendering: `unsatisfiable` is reachable in this repository from **one
    // policy on one row**. Section 4 says the value stays in the interface
    // because `JP-R3` needs `status` total for Q24's variants too; this is that
    // sentence with an address.
    const said = [...BY_KEY].filter(([, c]) => c.status === 'unsatisfiable').map(([k]) => k);
    equal(said, ['all-exit/live-token-requiring-arrival'],
      'JP-R8`s refinement on the all-branches-exited row — and since ADR 0025 that cell is a ' +
      'SHIPPED policy answering, not a variant. `arrival-count-decrementing` cannot say it ' +
      'either: JP-R7 changes when N is reached, not whether "not yet" can be told from ' +
      '"never", which is half of why ADR 0025 refused it');
  });

  test('the divergence is exactly where the spec says it is', () => {
    // **This is Q4's answer in one assertion.** Written from section 3, not read
    // off the run: the two policies differ on precisely those rows where a branch
    // finished WITHOUT arriving, because that is the only event arrival-count
    // ignores and live-token counts.
    const diverge = ALL
      .filter((r) => cellOf(r, 'arrival-count').status !== cellOf(r, 'live-token').status)
      .map(({ scenario }) => scenario.key);
    equal(diverge, ['routed-away', 'lost-settled', 'lost-resolved', 'optional-null', 'all-exit', 'six-events'],
      'six of nine rows. The three they agree on are the three where every branch that opened ' +
      'either arrived or is still live — and every row where a branch left the region by any ' +
      'other road, arrival-count waits forever');
    const agree = ALL.filter((r) => cellOf(r, 'arrival-count').status === cellOf(r, 'live-token').status)
      .map(({ scenario }) => scenario.key);
    equal(agree, ['all-arrive', 'suspended', 'resumed'],
      'and they agree on the human rows: a suspended branch is still live under both, so ' +
      'neither reports a run waiting on a person as anything but waiting');
  });

  test('Q7: every non-joined cell is labelled, and a stuck join needs no clock', () => {
    const verdicts = new Map([...BY_KEY].map(([k, c]) => [k, c.verdict] as const));
    // Ten stuck cells across four columns — six under `arrival-count`, three
    // under `JP-R7`'s variant on the rows its one line does not reach, and one
    // under `JP-R8`'s, which is the only cell here that is stuck **having said
    // so**. All of them a join that will never fire with nothing running and
    // nobody to ask.
    const stuck = [...verdicts].filter(([, v]) => v === 'stuck').map(([k]) => k);
    equal(stuck, [
      'routed-away/arrival-count',
      'lost-settled/arrival-count', 'lost-settled/arrival-count-decrementing',
      'lost-resolved/arrival-count', 'lost-resolved/arrival-count-decrementing',
      'optional-null/arrival-count',
      'all-exit/arrival-count', 'all-exit/live-token-requiring-arrival',
      'six-events/arrival-count', 'six-events/arrival-count-decrementing',
    ], 'a stuck join is decidable from the log alone: every dispatched task has an outcome, no ' +
       'branch is parked on a person, and the join has not fired. A timeout would add a ' +
       'wall-clock guess on top of an answer that is already certain');
    ok(![...verdicts.values()].includes('in-flight'),
      'and every row is driven to quiescence, so no cell is reporting "not finished yet" as ' +
      'though it were a result');
  });

  /**
   * **`JP-R12` — what a satisfied join carries.** Every expectation below is
   * written by hand from `spec/join-policy.md` section 4 and the row's own steps,
   * before it was run: *one entry per branch that emitted `branch.arrived`, keyed
   * by its `branchPath`, valued by what that branch carried into the join*, with
   * keys in ascending segment-wise-numeric `branchPath` order.
   *
   * **`ARRIVED_AT_JOIN` is the hand-written half and it is written as PATHS, not
   * as values**, so it says what `JP-R12`'s key set means — *which branches
   * arrived* — and cannot be satisfied by a harness echoing what it was given.
   * The VALUES are then looked up in the scenario's own `steps`, which are
   * hand-written fixtures (`doc/workflow.md` section 5 rule 4), so **no expected
   * value in this test is read from the driver**. That is rule 8 obligation (c)
   * applied where this repository has never had to apply it: all eight recorded
   * instances of a value read from the code under test are in `examples/**`.
   *
   * **The scope that claim holds at, stated rather than generalised**
   * (`doc/workflow.md` section 1 rule 5's writing clause). It is true of every
   * value here, and the GUARDS behind it are not uniform:
   *
   * | | what binds it if the source is swapped |
   * |---|---|
   * | every depth-1 key and value | the second-route test below, whose `stepResults` carries an `ingest` control no payload-derived source can satisfy, plus `ranKeys === declaredKeys` |
   * | `nested-all-arrive`'s inner collection | additionally the key-order test's `['1.0', '1.1']` literal |
   * | the other three depth-2 inner collections | **`INNER_COLLECTION` and nothing else** |
   *
   * The adequacy reader measured that last row: swapping `INNER_COLLECTION` for
   * `payload['1']` **and** breaking the driver so a nested join with one arrival
   * carries `{}` is green, while the driver defect alone costs 1. The values are
   * hand-written today and the claim is true; what is not true is that anything
   * would notice if they stopped being. **The second-route test below now runs over
   * the depth-2 rows as well**, which is that row closed.
   */
  const ARRIVED_AT_JOIN: Record<string, string[]> = {
    // depth 1 — `spec/join-policy.md` section 2's three terminal events decide
    // this, and only `branch.arrived` puts a key in.
    'all-arrive': ['0', '1'],
    'routed-away': ['0'], //           branch 1 reached an `end`  -> exited, no key
    'lost-settled': ['0'], //          branch 1 failed, no eligible edge -> lost
    'lost-resolved': ['0'], //         branch 1 resolved `failed` -> lost
    'optional-null': ['1'], //         branch 0 failed to an `end`; reviewB arrives
    'resumed': ['0', '1'], //          branch 1 suspended, resolved `done`, arrived
    'all-exit': [], //                 NOTHING arrived. `{}`, and it is live
    'six-events': ['2'], //            0 lost, 1 exited, 2 suspended-resumed-arrived
    // depth 2 — the outer region only. Branch `1` of `outer` is the INNER JOIN's
    // own exit, so its value is the inner region's collection rather than a task
    // result, and it is declared separately below.
    'nested-all-arrive': ['0', '1'],
    'nested-inner-lost': ['0', '1'],
    'nested-inner-exit': ['0', '1'],
    // `live-token-requiring-arrival` declares the inner join UNSATISFIABLE here,
    // so `JP-R10` loses outer branch 1 and it has no key. Every other column
    // fires the inner join carrying `{}`. **One row, two different key sets** —
    // which is why this entry is per COLUMN and the rest are per row.
    'nested-inner-all-exit': ['0', '1'],
  };

  /** Per-column overrides, for the one row whose columns disagree. */
  const ARRIVED_BY_COLUMN: Record<string, string[]> = {
    'nested-inner-all-exit/live-token-requiring-arrival': ['0'],
  };

  /**
   * The branch path each region member's TASK sits at — hand-written from each
   * flow in `flows.ts`, so the value lookup below goes through the fixture rather
   * than through `branchPathOf`.
   */
  const TASK_AT: Record<string, Record<string, string>> = {
    'all-arrive': { '0': 'r1:scoreA:0:0', '1': 'r1:scoreB:1:0' },
    'routed-away': { '0': 'r1:scoreA:0:0' },
    'lost-settled': { '0': 'r1:scoreA:0:0' },
    'lost-resolved': { '0': 'r1:scoreA:0:0' },
    'optional-null': { '1': 'r1:reviewB:1:0' },
    'resumed': { '0': 'r1:scoreA:0:0', '1': 'r1:scoreB:1:0' },
    'all-exit': {},
    'six-events': { '2': 'r1:arriveC:2:0' },
    'nested-all-arrive': { '0': 'r1:scoreA:0:0' },
    'nested-inner-lost': { '0': 'r1:scoreA:0:0' },
    'nested-inner-exit': { '0': 'r1:scoreA:0:0' },
    'nested-inner-all-exit': { '0': 'r1:scoreA:0:0' },
  };

  /**
   * Branch `1` of every depth-2 row is the INNER join's exit, so its value is
   * `JP-R12` applied one level down. Written out rather than computed, because
   * computing it would be running the rule to check the rule.
   */
  const INNER_COLLECTION: Record<string, unknown> = {
    'nested-all-arrive': { '1.0': { from: 'scoreC' }, '1.1': { from: 'scoreD' } },
    'nested-inner-lost': { '1.0': { from: 'scoreC' } }, //  1.1 failed -> lost
    'nested-inner-exit': { '1.0': { from: 'scoreC' } }, //  1.1 bailed -> exited
    'nested-inner-all-exit': {}, //                          both bailed -> nothing arrived
  };

  /** The result a fixture step gave the task at `path`, from `steps` alone. */
  function fixtureResultAt(scenario: { key: string; steps: readonly unknown[] }, path: string): unknown {
    const taskId = TASK_AT[scenario.key]?.[path];
    if (taskId === undefined) return undefined;
    // The LAST step naming that task wins, which is `spec/outcome-record.md`
    // section 7's effective outcome read off the fixture: a resolution following
    // a settlement replaces its `result`.
    let out: unknown = null;
    let seen = false;
    for (const raw of scenario.steps) {
      const st = raw as { do: string; taskId: string; result?: unknown };
      if (st.taskId !== taskId) continue;
      seen = true;
      out = st.result ?? null;
    }
    return seen ? out : undefined;
  }

  test('JP-R12 — a satisfied join carries the arrived branches, keyed by branchPath', () => {
    // **This test replaces `a satisfied join carries `null``**, which asserted the
    // placeholder `spec/join-policy.md` section 4 called one. Its second half is
    // KEPT below and is what stops a harness returning a constant from passing:
    // asserting only the join's payload passed a harness reporting `null` for
    // everything, because every payload in every cell was `null`. The same trap is
    // live in the other direction now — a harness echoing the arrivals map would
    // satisfy the first half — which is why the expectations come from
    // `ARRIVED_AT_JOIN` and the fixture `steps` and not from a `Cell`.
    const fired = [...ALL, ...NESTED_ALL].flatMap(({ scenario, cells }) =>
      cells.filter((c) => c.joinFired)
        .map((c) => [scenario, c] as const));

    equal(fired.length, 34,
      'thirty-four of the fifty-two cells fire a join. Per column, per depth: **22 of the 36 ' +
      'depth-1 cells** — arrival-count 2, live-token 8, arrival-count-decrementing 5, ' +
      'live-token-requiring-arrival 7 — plus **12 of the 16 depth-2 cells** — arrival-count 1 ' +
      '(only nested-all-arrive), live-token 4, arrival-count-decrementing 3 (not ' +
      'nested-inner-lost), live-token-requiring-arrival 4. An inexact bound here would let the ' +
      'loop below shrink without anything saying so. **The first version of this line said 32 ' +
      'and was wrong in the depth-2 half**, which is the bound doing its job on the author ' +
      'before it could do it on anyone else');

    // **Counted from what the loops DID, never from the lists they were handed** —
    // rule 8 (d), and W33's adequacy reader's finding applied before a reader had
    // to make it again. The author's first version bounded `fired.length` above and
    // then looped over `fired`, so `fired.slice(0, 1)` cost **0**; and nothing at
    // all counted the inner per-key loop, so `expectedPaths.slice(0, 0)` cost 0
    // too. A list compared to a copy of itself says nothing about how many entries
    // a `for` consumed.
    let ranCells = 0;
    let ranKeys = 0;
    let declaredKeys = 0;
    for (const [scenario, c] of fired) {
      ranCells++;
      const where = `${scenario.key}/${c.policyId}`;
      const payload = c.payloads[scenario.downstream] as Record<string, unknown>;
      const expectedPaths = ARRIVED_BY_COLUMN[where] ?? ARRIVED_AT_JOIN[scenario.key]!;
      declaredKeys += expectedPaths.length;

      // **The KEY ORDER is asserted, not just the key set** — `deepEqual` on
      // arrays is order-sensitive where a set comparison would not be. The
      // hazard is invisible at depth 1, where the language re-orders
      // integer-like keys ascending whatever the insertion order; it is live at
      // depth 2, where dotted keys keep insertion order and insertion order is
      // SETTLEMENT order.
      equal(Object.keys(payload), expectedPaths,
        `${where}: JP-R12 — the join's payload keys are exactly the branch paths that emitted ` +
        `branch.arrived, in ascending segment-wise-numeric order. Got ` +
        `${JSON.stringify(Object.keys(payload))}, expected ${JSON.stringify(expectedPaths)}`);

      for (const path of expectedPaths) {
        ranKeys++;
        const inner = INNER_COLLECTION[scenario.key];
        const expected = path === '1' && inner !== undefined
          ? inner
          : fixtureResultAt(scenario, path);
        equal(payload[path], expected,
          `${where}: branch ${path} carried into the join what its own node produced — ` +
          'read from this scenario`s hand-written steps, never from the driver ' +
          '(`doc/workflow.md` section 5 rule 8 (c))');
      }
    }

    equal(ranCells, 34, 'the loop VISITED every firing cell — counted from what it did, which is a ' +
      'different fact from `fired.length` above and is what `fired.slice(0, 1)` would break');
    equal(ranKeys, 51, 'fifty-one keys were compared across those cells. DERIVED per row, as ' +
      '(declared paths) x (firing cells): depth 1 gives 28 — all-arrive 2x4, resumed 2x4, ' +
      'routed-away 1x3, optional-null 1x3, lost-settled 1x2, lost-resolved 1x2, six-events 1x2, ' +
      'all-exit 0x2 — and depth 2 gives 23: nested-all-arrive 2x4 = 8, nested-inner-lost 2x2 = 4, ' +
      'nested-inner-exit 2x3 = 6, and nested-inner-all-exit 2+2+1 = 5, because ' +
      'live-token-requiring-arrival declares only branch 0 there. 28 + 23 = 51');
    equal(ranKeys, declaredKeys,
      'and the number of keys the loop compared equals the number the DECLARED table asked for — ' +
      'two independently accumulated totals, one from `ARRIVED_AT_JOIN`/`ARRIVED_BY_COLUMN` and one ' +
      'from the iteration. This is what stops `expectedPaths` being re-sourced from the payload: ' +
      'the declared total would then no longer be read at all, and a dropped key would move `ranKeys` ' +
      'without moving anything else');
  });

  test('JP-R12 — the value under each key is the FIXTURE`s result, by a second route', () => {
    // **Rule 8's *a survivor is one only once a second independent route confirms
    // the clause was reachable*, built in rather than run once.** The test above
    // reads `TASK_AT` — a hand-written map — to find which fixture step supplies
    // a key's value. This one reads nothing but the scenario and the payload, and
    // asserts that **every value under a depth-1 key appears verbatim among that
    // row's own step results**. If `TASK_AT` were wrong, the test above would
    // compare against `undefined` and this one would still catch a payload
    // carrying a value no step ever produced.
    let checked = 0;
    let checkedNested = 0;
    for (const { scenario, cells } of ALL) {
      const stepResults = scenario.steps
        .map((st) => JSON.stringify((st as { result?: unknown }).result ?? null));
      // **A NEGATIVE control on the SAME expression the claim reads**, so
      // `stepResults` is load-bearing in a direction no payload-derived source can
      // satisfy. Without it this test's only binding was its own source: swapping
      // `stepResults` for the payload values makes `includes` trivially true, and
      // the compound probe — that swap PLUS a driver recording
      // `'NOT-FROM-ANY-STEP'` as every arrival — came back GREEN. `ingest`'s result
      // is a step result that NO branch ever carries into a join, because `ingest`
      // is upstream of the fan-out; so it must be present here and absent from
      // every collected payload, and one source cannot stand in for the other.
      //
      // **An earlier version put this control on a separate variable and it did not
      // work**: the probe swaps `stepResults`, the control read `allArriveSteps`,
      // and the compound stayed green. A control has to be on the expression the
      // probe changes — which is rule 8 (c)'s *change the SOURCE EXPRESSION and
      // nothing else* read from the defending side.
      if (scenario.key === 'all-arrive') {
        ok(stepResults.includes(JSON.stringify({ from: 'ingest' })),
          'the row`s own steps carry `ingest`s result, which is upstream of the fan-out and so ' +
          'appears in NO join collection. If this list came from the payloads it could not be here');
      }
      for (const c of cells.filter((x) => x.joinFired)) {
        const payload = c.payloads[scenario.downstream] as Record<string, unknown>;
        for (const [path, v] of Object.entries(payload)) {
          ok(stepResults.includes(JSON.stringify(v)),
            `${scenario.key}/${c.policyId}: branch ${path} carried ${JSON.stringify(v)}, which no ` +
            'step of this row ever produced — so it came from somewhere the fixture does not name');
          checked++;
        }
      }
    }
    // **Depth 2, which this test did not reach** — the adequacy reader's finding 4.
    // An inner join's collection is a VALUE of the outer one, so its leaves are the
    // inner branches' own results and the same *"it came from a step of this row"*
    // claim holds one level down. Without this loop, three of the four depth-2
    // collections were bound by `INNER_COLLECTION` alone.
    for (const { scenario, cells } of NESTED_ALL) {
      const stepResults = scenario.steps
        .map((st) => JSON.stringify((st as { result?: unknown }).result ?? null));
      for (const c of cells.filter((x) => x.joinFired)) {
        const payload = c.payloads[scenario.downstream] as Record<string, unknown>;
        const inner = payload['1'];
        if (inner === undefined || typeof inner !== 'object' || inner === null) continue;
        for (const [path, v] of Object.entries(inner as Record<string, unknown>)) {
          ok(stepResults.includes(JSON.stringify(v)),
            `${scenario.key}/${c.policyId}: inner branch ${path} carried ${JSON.stringify(v)}, ` +
            'which no step of this row ever produced');
          checkedNested++;
        }
      }
    }
    equal(checkedNested, 13,
      'thirteen INNER keys across the depth-2 rows. DERIVED as (inner keys) x (firing cells): ' +
      'nested-all-arrive 2 x 4 = 8, because both inner branches arrive; nested-inner-lost 1 x 2 = 2 ' +
      'and nested-inner-exit 1 x 3 = 3, because in each only scoreC reaches the inner join; and ' +
      'nested-inner-all-exit 0, because NOTHING arrives at its inner join so the collection is `{}` ' +
      'and has no leaves to check. 8 + 2 + 3 + 0 = 13. **The first version of this line said 16 ' +
      'while the comment beside it worked out 13**, which is the assertion catching the author ' +
      'rather than a reader — the third time in this item');

    equal(checked, 28,
      'twenty-eight depth-1 keys across the twenty-two firing depth-1 cells. Derived: ' +
      'all-arrive 2x4 = 8, resumed 2x4 = 8, routed-away 1x3 = 3, optional-null 1x3 = 3, ' +
      'lost-settled 1x2 = 2, lost-resolved 1x2 = 2, six-events 1x2 = 2, all-exit 0x2 = 0; ' +
      '8+8+3+3+2+2+2+0 = 28. Without this bound the loop above could iterate nothing and pass. ' +
      '**The first version of this line enumerated exactly these eight products and then wrote ' +
      '30**, which is a count of a list disagreeing with the list beside it — W31`s shape, and ' +
      'caught here by the assertion rather than by a reader');
  });

  test('JP-R12 — a branch that did NOT arrive has no key, and `{}` is a real answer', () => {
    // The two halves `spec/join-policy.md` section 4 states explicitly, asserted
    // separately from the table above so that deleting a row of `ARRIVED_AT_JOIN`
    // cannot take them with it.
    const routedAway = ALL.find((r) => r.scenario.key === 'routed-away')!;
    // Counted, because the author counted five other loops in this file and missed
    // this one — the adequacy reader's 5a. `.slice(0, 0)` here cost **0**.
    let ranRoutedAway = 0;
    for (const c of routedAway.cells.filter((x) => x.joinFired)) {
      ranRoutedAway++;
      const payload = c.payloads[routedAway.scenario.downstream] as Record<string, unknown>;
      ok(!('1' in payload),
        `${c.policyId}: P1's own case — branch 1 was routed away to an \`end\`, so it never ` +
        'arrived and JP-R12 gives it NO key. `1: null` would say it arrived carrying nothing');
      ok('0' in payload, `${c.policyId}: and branch 0 DID arrive, so the absence above is a ` +
        'statement about branch 1 rather than about the payload being empty');
    }

    equal(ranRoutedAway, 3, 'three of routed-away`s four columns fire a join — arrival-count does ' +
      'not, because branch 1 exited and its N is never reached. Counted from what the loop DID');

    const allExit = ALL.find((r) => r.scenario.key === 'all-exit')!;
    const firedThere = allExit.cells.filter((x) => x.joinFired);
    equal(firedThere.length, 2,
      'live-token and arrival-count-decrementing fire this join with NOTHING arrived — ' +
      "ADR 0003's recorded cost for live-token, and the reason `{}` is a live case rather than " +
      'a defensive one');
    for (const c of firedThere) {
      equal(c.payloads[allExit.scenario.downstream], {},
        `${c.policyId}: every branch reached an \`end\`, so a join fired over a region nothing ` +
        'arrived at carries `{}` — an empty collection, not `null` and not a missing payload');
    }
  });

  test('JP-R12 — the key ORDER is numeric per segment, and depth 2 is where it can break', () => {
    // **The constructed case, because the corpus cannot express one on its own.**
    // Measured before the rule was written: integer-like object keys are
    // re-ordered ASCENDING by the language whatever the insertion order, so every
    // depth-1 row is deterministic for free and no depth-1 assertion can fail
    // here. Dotted keys are NOT: `1.1` inserted before `1.0` stays first. So the
    // depth-2 rows are the whole of this clause's live evidence AT L5, and this test
    // says so rather than looping over 52 cells and reporting coverage it has not
    // got.
    //
    // **What this test does NOT do is discriminate the ordering, and an earlier
    // version claimed it did.** It read *"this is the only place in the suite where
    // the sort is load-bearing"*. **False, and the adequacy reader measured it**:
    // every depth-2 matrix row settles `scoreC` before `scoreD`, so insertion order
    // here ALREADY equals sorted order and a lexicographic sort passes this test.
    // Emptying its loop while making the driver's sort lexicographic costs **1**
    // failure — and that failure is in `test/driver/map.test.ts`, on the map at
    // N = 12 settled descending, not here. **This asserts that the keys are dotted
    // and in ascending order on a row where they would be anyway**; the
    // discriminating fixture is at L2 and `JP-R12`'s Test column now says so.
    const probe: Record<string, number> = {};
    for (const k of ['1.1', '1.0']) probe[k] = 1;
    equal(Object.keys(probe), ['1.1', '1.0'],
      'the language does NOT re-order dotted keys — if this ever changes, the sort in ' +
      '`collectArrivals` becomes untestable and this test is what says so');

    const nested = NESTED_ALL.find((r) => r.scenario.key === 'nested-all-arrive')!;
    let ranNested = 0;
    for (const c of nested.cells.filter((x) => x.joinFired)) {
      ranNested++;
      const outer = c.payloads[nested.scenario.downstream] as Record<string, unknown>;
      const innerCollection = outer['1'] as Record<string, unknown>;
      equal(Object.keys(innerCollection), ['1.0', '1.1'],
        `${c.policyId}: the INNER join's collection is keyed by the inner branch paths in ` +
        'ascending order — dotted keys, which the language does NOT re-order');
    }
    equal(ranNested, 4, 'all four columns of nested-all-arrive fire and were checked — counted ' +
      'from what the loop DID. The adequacy reader emptied this loop for 0');
  });

  test('an ordinary edge forwards the previous node`s result, so `JP-R12` is the JOIN`s doing', () => {
    // **Kept from the test this replaced, and it is the half that stops a
    // constant.** Asserting only what the join carries passed a harness returning
    // `null` for everything; asserting only the arrivals map would pass a harness
    // echoing it. Both claims read the same `payloads` map, so neither a constant
    // nor an echo satisfies both.
    const allArrive = ALL.find((r) => r.scenario.key === 'all-arrive')!;
    for (const c of allArrive.cells) {
      equal(c.payloads['r1:scoreA:0:0'], { from: 'ingest' },
        `${c.policyId}: an ordinary edge forwards the previous node's result ` +
        '(`spec/flow-definition.md` section 3), so the join`s collection is a decision the JOIN ' +
        'makes and not something this harness reports for everything');
    }
  });

  test('the join\'s answer does not depend on the order branches settle in', () => {
    // `doc/concept.md` section 5 and `CLAUDE.md`: fan-out completion order is
    // genuinely non-deterministic and nothing may depend on it. `JP-R1`'s
    // determinism test re-runs the SAME order twice, which proves purity — not
    // order-independence. These are different properties and only one of them
    // was checked.
    const six = SCENARIOS.find((s) => s.key === 'six-events')!;
    const [ingest, lost, exited, suspend, resolve] = six.steps;
    const orders = [
      six.steps,
      [ingest!, exited!, lost!, suspend!, resolve!],
      [ingest!, suspend!, lost!, exited!, resolve!],
    ];
    for (const policy of [arrivalCount, liveToken]) {
      const verdicts = orders.map((steps) => {
        const c = runCell({ ...six, steps }, policy as JoinPolicy);
        return { status: c.status, verdict: c.verdict, joinFired: c.joinFired };
      });
      equal(verdicts[1], verdicts[0],
        `${policy.id}: reordering two terminal settlements changed the join's answer`);
      equal(verdicts[2], verdicts[0],
        `${policy.id}: suspending the third branch first changed the join's answer`);
    }
    // **And the honest half:** `arrival-count`'s `describe` IS order-dependent —
    // `arrived` is a list in arrival order. That is a display value (`JP-R2`), not
    // the answer, and the assertions above are on `status` for exactly that
    // reason. Recorded here rather than left for a reader to discover.
    const flip = { ...SCENARIOS.find((s) => s.key === 'all-arrive')!, key: 'flipped' };
    const [ing, a, b] = flip.steps;
    const swapped = runCell({ ...flip, steps: [ing!, b!, a!] }, arrivalCount as JoinPolicy);
    equal(swapped.status, 'satisfied', 'the ANSWER is the same whichever branch arrives first');
    equal(swapped.describe, { need: 2, arrived: ['1', '0'] },
      'and the describe is not — which is why nothing routes on it');
  });

  test('JP-R1: the whole matrix is deterministic', () => {
    // Ladder L3 on the join seam: same scenario, same policy, twice.
    for (const { scenario, cells } of ALL) {
      const again = COLUMNS.map((policy) => runCell(scenario, policy));
      equal(again, cells, `${scenario.key}: a second identical run produced a different cell, so ` +
        'something in the seam is not a pure function of the event sequence');
    }
  });

  test('JP-R2: every describe in the matrix round-trips as JSON', () => {
    for (const { scenario, cells } of ALL) {
      for (const c of cells) {
        equal(JSON.parse(JSON.stringify(c.describe)), c.describe,
          `${scenario.key}/${c.policyId}: describe is how a matrix cell and a future UI report ` +
          'what the policy thought it was waiting for');
      }
    }
  });

  test('the matrix runs four columns: the two shipped, and Q24`s two variants', () => {
    equal([...MATRIX_POLICY_IDS],
      ['arrival-count', 'live-token', 'arrival-count-decrementing', 'live-token-requiring-arrival'],
      'the PINNED pair W4 compared, then JP-R7`s refinement, then JP-R8`s — the render order, ' +
      'written as a literal rather than derived. **It used to be `[...SHIPPED, ...VARIANT]` and ' +
      'that broke here**: ADR 0025 ships one of the two refinements, so the derived order would ' +
      'have silently reshuffled the columns of P5`s exit artifact as a side effect of a decision ' +
      'about what a policy MEANS. What is shipped is asserted below, against `POLICIES` itself');
    equal([...MATRIX_POLICY_IDS].slice(0, 2), PINNED_POLICY_IDS,
      'and the two ADR 0003 was written from are still columns one and two, so its hand-copied ' +
      'table is still readable off the left of this one');
    equal([...MATRIX_POLICY_IDS].filter((id) => !SHIPPED_POLICY_IDS.includes(id)), VARIANT_POLICY_IDS,
      'and every column that is NOT shipped is a declared variant — a column defined in the ' +
      'test tree that nobody declared is how a fixture becomes evidence');
    equal(COLUMNS.map((p) => p.id), [...MATRIX_POLICY_IDS],
      'and the POLICY list agrees with the ID list. Two lists that must line up and are never ' +
      'compared is how a column silently becomes a duplicate of its neighbour — which would ' +
      'make a refinement`s column identical to the policy it refines, for the wrong reason');
    equal(new Set(COLUMNS.map((p) => p.id)).size, MATRIX_POLICY_IDS.length,
      'and no policy appears twice. `render.ts` prints from this same list, so this is the ' +
      'assertion that covers the EXIT ARTIFACT — while the renderer built a list of its own, ' +
      'duplicating a column there left the whole gate green and the printed table wrong');
    equal(Object.keys(POLICIES).sort(), SHIPPED_POLICY_IDS,
      'and `src/` exports exactly the policies section 3 names — **three since ADR 0025**, ' +
      'which adopted JP-R8`s refinement under its own id and refused JP-R7`s. The refused one ' +
      'is still RUN here and shipped nowhere, which is what keeps the refusal falsifiable');
    equal(SHIPPED_POLICY_IDS.filter((id) => !MATRIX_POLICY_IDS.includes(id as never)), [],
      '**and every SHIPPED policy is a column of this matrix.** True since P1 and asserted by ' +
      'nothing until W16`s adequacy reader added a fourth policy to POLICIES and to the spec and ' +
      'watched it ship with five clause assertions, no column, no behavioural suite and no ' +
      'unsatisfiable chain — 386 assertions, all green. JP-R9 makes the two NAME sets agree and ' +
      'says nothing about evidence; this is the line that does');
    equal(Object.keys(POLICIES).filter((id) => VARIANT_POLICY_IDS.includes(id)), [],
      'and nothing this file calls a variant has an entry in POLICIES. JP-R7 and JP-R8 say a ' +
      'refinement gets its own id; a refinement that acquired one WITHOUT an ADR is the exact ' +
      'thing both rules were written to catch');
  });

  test('the rendered table is the exit artifact, and its SHAPE is asserted cell by cell', () => {
    // **Three versions of this test, and the second was still weak.** W4's
    // asserted only that each row key appeared and the line count was right, so
    // emptying every cell body survived it. W15's asserted cell CONTENT with
    // `line.includes(...)` over the whole row — which is **order-blind**, so the
    // adequacy reader reversed the column order inside `renderTable` and it
    // passed, and separately collapsed all four cells into one, dropped the
    // separator row, dropped the title and dropped the event stream, all green.
    //
    // So the line is now SPLIT and each field is asserted in its own position.
    // `renderMatrix()` is imported from `./table.ts` — **the same function
    // `render.ts` prints**, which is the other half of the repair: the renderer
    // used to be a script the gate never executed, holding a column list nobody
    // compared.
    const lines = renderMatrix().split('\n');
    const rows = ALL;
    equal(lines.length, rows.length + 2, 'header, rule, and one line per row');
    equal(lines[0], `| row | ${MATRIX_POLICY_IDS.join(' | ')} |`,
      'FOUR columns, named and in order — W15`s first declared output');
    equal(lines[1], `|---|${MATRIX_POLICY_IDS.map(() => '---').join('|')}|`,
      'and a separator with one entry per column. Without this the output stops being valid ' +
      'markdown and the artifact a person is meant to LOOK at does not render at all');

    for (const [i, { scenario, cells }] of rows.entries()) {
      // `| row | c0 | c1 | c2 | c3 |` splits to ['', row, c0, c1, c2, c3, ''].
      const fields = lines[i + 2]!.split('|');
      equal(fields.length, MATRIX_POLICY_IDS.length + 3,
        `${scenario.key}: the row has ${fields.length - 3} cells, not ${MATRIX_POLICY_IDS.length}. ` +
        'Joining the cells without a separator collapsed four columns into one and every ' +
        '`includes` assertion still passed');

      const rowCell = fields[1]!;
      ok(rowCell.includes(`**${scenario.key}**`), `${scenario.key} is missing from the table`);
      ok(rowCell.includes(scenario.title),
        `${scenario.key}: the row does not carry its title, so the table names the rows and does ` +
        'not say what they ARE');
      ok(rowCell.includes(cells[0]!.events.join(' ')),
        `${scenario.key}: the row does not carry its region-event stream — the policy's whole ` +
        'input, and the only thing that lets a reader check a cell against the spec by eye');

      // **By POSITION, not by presence.** The reader transposed the cells against
      // their own asserted header and nothing noticed, because every assertion
      // searched the whole line.
      for (const [j, id] of MATRIX_POLICY_IDS.entries()) {
        const cell = fields[j + 2]!;
        const c = cells.find((x) => x.policyId === id)!;
        ok(cell.includes(`\`${c.status}\``),
          `${scenario.key}: column ${j} is meant to be ${id} and does not carry "${c.status}"`);
        ok(cell.includes(`**${c.verdict}**`),
          `${scenario.key}: column ${j} (${id}) does not carry "${c.verdict}"`);
        ok(cell.includes(JSON.stringify(c.describe)),
          `${scenario.key}: ${id}'s describe is not in ITS OWN column, so a reader cannot see ` +
          'what the policy thought it was waiting for — which is the only reason to print it');
      }
    }
  });
});


/**
 * **Which rows each refinement changes, as an exact sorted list.**
 *
 * P5 measured this as two counts — three and one. A count passes on arithmetic:
 * a policy edit that repaired a different row and broke one of these would leave
 * both numbers untouched. The lists below are the same measurement made
 * falsifiable, and each is asserted **three ways** that fail independently:
 *
 *   1. the literal the work item declares;
 *   2. a predicate over the row's own region-event stream, derived from
 *      `spec/join-policy.md` section 3 with no code open;
 *   3. what the four columns actually did.
 *
 * `doc/workflow.md` section 5 rule 1 asks for the derivation of a non-obvious
 * value. (2) IS the derivation, executed — so a reader does not have to trust
 * that (1) was derived rather than pasted.
 */
suite('L5 — the fourth column: what each refinement changes', (test) => {
  /**
   * A row's stream reduced to the five numbers section 3's definitions read.
   * `U` is *opened but never terminal* — a branch parked on a person, which
   * `JP-R5` says legally emits no terminal event at all.
   */
  const counts = (events: string[]) => {
    const opened = new Set<string>();
    const terminal = new Map<string, string>();
    for (const e of events) {
      const type = e.slice(0, e.indexOf('('));
      const branch = e.slice(e.indexOf(':') + 1, -1);
      if (type === 'opened') opened.add(branch);
      if (type === 'arrived' || type === 'exited' || type === 'lost') terminal.set(branch, type);
    }
    const n = (k: string) => [...terminal.values()].filter((v) => v === k).length;
    return { B: opened.size, A: n('arrived'), E: n('exited'), L: n('lost'), U: opened.size - terminal.size };
  };

  /**
   * **The ANSWER, which is status plus what the driver did with it — not
   * `describe`.** `arrival-count-decrementing` has a different `describe` from
   * `arrival-count` on every row carrying an exit, `six-events` included, where
   * N reads 2 instead of 3 and the join still never fires. `JP-R2` calls
   * `describe` a display value and nothing routes on it, so a list built from it
   * would report a row as "changed" that behaves identically.
   */
  const answer = (c: Cell) => ({ status: c.status, verdict: c.verdict, joinFired: c.joinFired });

  const changedBy = (base: string, variant: string) =>
    ALL.filter((r) => !deepEqual(answer(cellOf(r, base)), answer(cellOf(r, variant))))
      .map(({ scenario }) => scenario.key).sort();

  test('JP-R7 changes exactly three rows, and the predicate says which three', () => {
    // Section 3: `arrival-count` is satisfied iff A >= B; the variant iff
    // A >= B - E. Since A + E + L + U = B, the second is A >= A + L + U, i.e.
    // L = 0 and U = 0; and they can only differ while A < B, i.e. E > 0.
    // **So: at least one branch exited, none was lost, and none is still live.**
    const predicted = SCENARIOS.filter((sc) => {
      const { E, L, U } = counts(EXPECTED[sc.key]!.events);
      return E >= 1 && L === 0 && U === 0;
    }).map((sc) => sc.key).sort();

    equal(predicted, ['all-exit', 'optional-null', 'routed-away'],
      'the three rows whose only non-arrival terminals are `exited`. `six-events` carries an ' +
      'exit AND a `lost`, so N is still short by one and it stays waiting — which is JP-R7`s ' +
      'own argument that the fix is fitted to the row it was written for');
    equal(changedBy('arrival-count', 'arrival-count-decrementing'), predicted,
      'and that is what the column does. **This is the claim ADR 0003 and the register both ' +
      'got wrong**: JP-R7 does NOT repair "only the row P1 named" — it repairs three, and the ' +
      'ADR`s own 2026-08-30 Correction already says why (optional-null and all-exit are ' +
      'branch-index permutations of routed-away). The register is corrected; the ADR is W16`s');
  });

  test('JP-R8 changes exactly one row, and the predicate says which', () => {
    // Section 3: `live-token` is satisfied when the count reaches zero having
    // been positive — i.e. every opened branch is terminal (U = 0, B > 0). The
    // variant then answers `unsatisfiable` instead of `satisfied` iff A = 0.
    const predicted = SCENARIOS.filter((sc) => {
      const { B, A, U } = counts(EXPECTED[sc.key]!.events);
      return B > 0 && U === 0 && A === 0;
    }).map((sc) => sc.key).sort();

    equal(predicted, ['all-exit'],
      'one row: the only one where every branch finishes and none of them arrives. `suspended` ' +
      'has a branch still live, so both say `waiting` and the refinement never gets to speak');
    equal(changedBy('live-token', 'live-token-requiring-arrival'), predicted,
      'and that is what the column does — on the exact row ADR 0003 records as live-token`s ' +
      'cost. **The two refinements are not symmetric**: three rows against one, and this one ' +
      'is a behaviour change to the blessed policy rather than an added capability');
  });

  test('the lists are on the ANSWER, and `describe` alone changes a fourth row', () => {
    // Recorded rather than left for a reader to find: the two comparisons above
    // would report four rows and two if they read `describe`. Naming the row
    // makes the choice checkable instead of a silent convention.
    const six = ALL.find((r) => r.scenario.key === 'six-events')!;
    equal(cellOf(six, 'arrival-count').describe, { need: 3, arrived: ['2'] }, 'N is three');
    equal(cellOf(six, 'arrival-count-decrementing').describe, { need: 2, arrived: ['2'] },
      'and the variant decremented it on the exit — a different describe, the same answer, so ' +
      'the row is NOT on JP-R7`s list. A list built from `describe` would say it was');
    equal(answer(cellOf(six, 'arrival-count')), answer(cellOf(six, 'arrival-count-decrementing')),
      'the answer is identical: still waiting, still stuck, the join still never fired');
  });

  test('the refinements do not converge — three columns, three different answers', () => {
    // The whole reason ADR 0025 is a decision rather than a tidy-up. On
    // `all-exit` the three live policies say three different things about the
    // same event stream, and `spec/join-policy.md` section 4 gives each a
    // different consequence.
    const row = ALL.find((r) => r.scenario.key === 'all-exit')!;
    equal(cellOf(row, 'arrival-count').status, 'waiting', 'waits forever, and cannot say so');
    equal(cellOf(row, 'live-token').status, 'satisfied', 'fires a join NO branch reached');
    equal(cellOf(row, 'arrival-count-decrementing').status, 'satisfied',
      'JP-R7`s variant reaches live-token`s answer here by the other road — N is decremented ' +
      'to zero — which is why "the two policies are equivalent" would have looked like a pass');
    equal(cellOf(row, 'live-token-requiring-arrival').status, 'unsatisfiable',
      'and only JP-R8`s variant declines and says why');
  });
});

// =============================================================================
// L5 at DEPTH 2 — W22, and the evidence for
// [ADR 0030](../../doc/decisions/0030-a-join-is-transitive-and-a-dead-join-ends-the-branch-it-sits-in.md)
// =============================================================================

/**
 * **A depth-2 row needs a per-column event stream, and a depth-1 row does not.**
 *
 * The nine rows above assert one `events` list and then assert it is IDENTICAL
 * under all four columns, on the stated ground that *"a policy cannot change what
 * the driver emits"*. **At depth 2 that ground is false**, and it is one of this
 * item's findings: an inner join's FIRING enters the outer join, which emits
 * `arrived(outer:1)` — so whether the outer region sees an event at all depends
 * on what the inner region's policy concluded. A join is an event source for the
 * region enclosing it.
 *
 * The comparison survives, and the shape of the fix says why: **the four columns
 * still see identical input up to the inner join's verdict**, which is the prefix
 * below. What differs after it is a *result*, not an input.
 */
interface NestedExpected {
  /** Identical under all four columns: everything up to the inner join's verdict. */
  prefix: string[];
  /** What each column appends after it — the inner join's verdict, made visible. */
  tail: { ac: string[]; lt: string[]; acDec: string[]; ltArr: string[] };
  /** The OUTER join's answer — what `Cell.status`/`describe` report. */
  outer: { ac: Answer; lt: Answer; acDec: Answer; ltArr: Answer };
  /** The INNER join's answer, from `Cell.regions`. No verdict: see `st`. */
  inner: Record<'ac' | 'lt' | 'acDec' | 'ltArr', Pick<Answer, 'status' | 'describe'>>;
  /** The depth-1 row this row's INNER region is claimed to reproduce. */
  correspondsTo: string;
}

/**
 * An answer with **no verdict at all**: a region that is not the row's `fanoutId`
 * has none.
 *
 * It used to stamp `verdict: 'joined'` on every one of these — documented as
 * never read, and never read. **W22's conformity reader**: a wrong literal in an
 * expectation table is one refactor away from being read, and three of these
 * rows have a depth-1 counterpart whose verdict is `stuck`. The type is narrowed
 * so the value cannot be written rather than the comment being trusted.
 */
const st = (status: string, describe: JsonValue): Pick<Answer, 'status' | 'describe'> =>
  ({ status, describe });

/**
 * Derived by hand from `spec/join-policy.md` sections 2 and 3 and the three
 * flows, **before any of it was run** (`doc/workflow.md` section 5 rule 1).
 *
 * The shared opening, for every row: `outer` is the entry, so `start` opens both
 * outer branches at their own paths; `scoreA` settles and arrives; `scoreB`
 * settles and enters `inner`, which opens its two branches at `1.0` and `1.1`.
 * `pathOf` is `spec/task-id.md` section 1's *"a property of the node"*, and
 * [W21](../../doc/work-items/w21-the-branch-path-is-a-path.md) is what made that
 * literally true.
 */
const OPENING = [
  'opened(outer:0)', 'opened(outer:1)', 'arrived(outer:0)',
  'opened(inner:1.0)', 'opened(inner:1.1)',
];

/** The inner join fired, so it entered `outerJoin` at the path its REGION sits at. */
const OUTER_ARRIVED = ['arrived(outer:1)'];
/** The inner join was declared dead, so W22's emission ends the outer branch. */
const OUTER_LOST = ['lost(outer:1)'];

const NESTED_EXPECTED: Record<string, NestedExpected> = {
  // The depth-2 control row. If the columns disagreed here, nesting would be
  // changing something before any branch had done anything interesting.
  'nested-all-arrive': {
    prefix: [...OPENING, 'arrived(inner:1.0)', 'arrived(inner:1.1)'],
    tail: { ac: OUTER_ARRIVED, lt: OUTER_ARRIVED, acDec: OUTER_ARRIVED, ltArr: OUTER_ARRIVED },
    inner: {
      ac: st('satisfied', ac(2, ['1.0', '1.1'])), lt: st('satisfied', lt(0)),
      acDec: st('satisfied', ac(2, ['1.0', '1.1'])), ltArr: st('satisfied', ltA(0, 2)),
    },
    outer: {
      ac: satisfied(ac(2, ['0', '1'])), lt: satisfied(lt(0)),
      acDec: satisfied(ac(2, ['0', '1'])), ltArr: satisfied(ltA(0, 2)),
    },
    correspondsTo: 'all-arrive',
  },

  // `lost-settled` one level down. The two arrival-counting columns never reach
  // 2 and the inner join hangs; both live-token columns see the count reach zero
  // and fire, so the outer branch arrives.
  'nested-inner-lost': {
    prefix: [...OPENING, 'arrived(inner:1.0)', 'lost(inner:1.1)'],
    tail: { ac: [], lt: OUTER_ARRIVED, acDec: [], ltArr: OUTER_ARRIVED },
    inner: {
      ac: st('waiting', ac(2, ['1.0'])), lt: st('satisfied', lt(0)),
      acDec: st('waiting', ac(2, ['1.0'])), ltArr: st('satisfied', ltA(0, 1)),
    },
    outer: {
      ac: waiting(ac(2, ['0']), 'stuck'), lt: satisfied(lt(0)),
      acDec: waiting(ac(2, ['0']), 'stuck'), ltArr: satisfied(ltA(0, 2)),
    },
    correspondsTo: 'lost-settled',
  },

  // `routed-away` one level down — P1's own case inside a nested region. The
  // variant column decrements `N` on the exit and so reaches 1, which is the one
  // thing that separates it from plain arrival-counting.
  'nested-inner-exit': {
    prefix: [...OPENING, 'arrived(inner:1.0)', 'exited(inner:1.1)'],
    tail: { ac: [], lt: OUTER_ARRIVED, acDec: OUTER_ARRIVED, ltArr: OUTER_ARRIVED },
    inner: {
      ac: st('waiting', ac(2, ['1.0'])), lt: st('satisfied', lt(0)),
      acDec: st('satisfied', ac(1, ['1.0'])), ltArr: st('satisfied', ltA(0, 1)),
    },
    outer: {
      ac: waiting(ac(2, ['0']), 'stuck'), lt: satisfied(lt(0)),
      acDec: satisfied(ac(2, ['0', '1'])), ltArr: satisfied(ltA(0, 2)),
    },
    correspondsTo: 'routed-away',
  },

  // **The row this item exists for.** `all-exit` one level down: the inner join
  // is reached by nothing. Four columns, FOUR different tails, and the fourth's
  // is the event W22 added — the inner join is declared dead and the outer branch
  // it sits in ends.
  'nested-inner-all-exit': {
    prefix: [...OPENING, 'exited(inner:1.0)', 'exited(inner:1.1)'],
    tail: { ac: [], lt: OUTER_ARRIVED, acDec: OUTER_ARRIVED, ltArr: OUTER_LOST },
    inner: {
      ac: st('waiting', ac(2, [])), lt: st('satisfied', lt(0)),
      // `need` decremented to zero against an empty arrival list — ADR 0025's
      // refused cost, and at depth 2 it produces a REAL arrival for the outer join.
      acDec: st('satisfied', ac(0, [])), ltArr: st('unsatisfiable', ltA(0, 0)),
    },
    outer: {
      ac: waiting(ac(2, ['0']), 'stuck'), lt: satisfied(lt(0)),
      acDec: satisfied(ac(2, ['0', '1'])),
      // The outer join FIRES: its live count reached zero having been positive,
      // and `scoreA` arrived. The dead region is `inner`, and `RunState.outcome`
      // is `stuck` because `regions.inner.joined === false` — asserted in
      // `chain.test.ts`, not here, because a `Cell` cannot see the fold.
      ltArr: satisfied(ltA(0, 1)),
    },
    correspondsTo: 'all-exit',
  },
};

const NESTED = NESTED_SCENARIOS.map((scenario) => ({
  scenario,
  cells: MATRIX_COLUMNS.map((p) => runCell(scenario, p)),
}));

/**
 * **The four columns, keyed to `NestedExpected`'s four fields.**
 *
 * **Pinned to `MATRIX_POLICY_IDS` below, because it was a private literal and
 * dropping a pair from it cost NOTHING** — W22's adequacy reader, BLOCKING. The
 * columns are looped *inside* test cases, so removing one changed neither the
 * failure count nor the assertion count, while the render kept printing four from
 * `MATRIX_POLICY_IDS` — the artifact advertising coverage the assertions no
 * longer had. Confirmed by a second route twice: corrupting
 * `nested-inner-exit.inner.acDec` costs 1 normally and **0** with the acDec pair
 * dropped, and the same for two `ltArr` values. This is W15's *"a whole column
 * deleted from ADR 0025's pasted table"* reproduced in the depth-2 half.
 *
 * The depth-1 suite pins its four three separate ways; this had none.
 */
const COLS = [
  ['ac', 'arrival-count'], ['lt', 'live-token'],
  ['acDec', 'arrival-count-decrementing'], ['ltArr', 'live-token-requiring-arrival'],
] as const;

suite('L5 at depth 2 — the join over a nested fan-out', (test) => {
  for (const { scenario, cells } of NESTED) {
    const want = NESTED_EXPECTED[scenario.key]!;
    const cell = (id: string) => cells.find((c) => c.policyId === id)!;

    test(`${scenario.key}: every column sees the same input up to the inner join verdict`, () => {
      for (const [, id] of COLS) {
        equal(cell(id).events.slice(0, want.prefix.length), want.prefix,
          `${scenario.key}/${id}: the four columns must be compared on one input, and everything ` +
          'before the inner join concluded IS one input. A difference here would be the driver ' +
          'emitting differently per policy, which nothing may do');
      }
    });

    test(`${scenario.key}: and then each column's own tail`, () => {
      for (const [key, id] of COLS) {
        equal(cell(id).events.slice(want.prefix.length), [...want.tail[key]],
          `${scenario.key}/${id}: what the outer region sees AFTER the inner join concluded is a ` +
          'result rather than an input — a join is an event source for the region enclosing it, ' +
          'which is the property depth 1 cannot have');
      }
    });

    test(`${scenario.key}: the OUTER join, which is what a Cell reports`, () => {
      for (const [key, id] of COLS) {
        const c = cell(id);
        equal({ status: c.status, describe: c.describe, verdict: c.verdict }, want.outer[key],
          `${scenario.key}/${id}: the outer join`);
      }
    });

    test(`${scenario.key}: the INNER join, which is what the row is about`, () => {
      for (const [key, id] of COLS) {
        const got = cell(id).regions['inner']!;
        equal({ status: got.status, describe: got.describe },
          { status: want.inner[key].status, describe: want.inner[key].describe },
          `${scenario.key}/${id}: the inner join. Without \`Cell.regions\` this is invisible, and ` +
          'the row then asserts the outer join while claiming to be about the inner one');
      }
    });

    test(`${scenario.key}: the row's declared fanout is one region, not two`, () => {
      // `regions[fanoutId]` and `status` read the same accessor for the same
      // region, so they cannot disagree — and if they ever do, one of the two has
      // been re-sourced from somewhere else.
      for (const [, id] of COLS) {
        const c = cell(id);
        equal({ status: c.regions['outer']!.status, describe: c.regions['outer']!.describe },
          { status: c.status, describe: c.describe },
          `${scenario.key}/${id}: Cell.regions[fanoutId] and Cell.status are the same region`);
      }
    });
  }
});

/**
 * **ADR 0030's central claim, as an assertion rather than as a paragraph.**
 *
 * Every nested row's INNER region behaves exactly as the depth-1 row of the same
 * shape — same status, same `describe`, under all four columns — with only the
 * branch paths renamed. That is what *transitive* means here: nesting adds no
 * mechanism, and a region does not behave differently for being inside another.
 */
suite('ADR 0030 — a region behaves the same whether or not it is nested', (test) => {
  /**
   * `region(inner)`'s branches are outer branch 1's children, so its paths are
   * `1.0` and `1.1` where the depth-1 row's are `0` and `1`. **Written as an
   * explicit map rather than by stripping a prefix**, because a strip would also
   * quietly "correspond" a path that was wrong in some other way.
   */
  const OUTER_PATHS: Record<string, string> = { '1.0': '0', '1.1': '1' };
  const rename = (d: JsonValue): JsonValue => {
    if (d === null || typeof d !== 'object' || Array.isArray(d)) return d;
    const o = d as { arrived?: unknown };
    if (!Array.isArray(o.arrived)) return d;
    return { ...d, arrived: o.arrived.map((p) => OUTER_PATHS[p as string] ?? p) } as JsonValue;
  };

  for (const { scenario, cells } of NESTED) {
    const want = NESTED_EXPECTED[scenario.key]!;
    test(`${scenario.key} reproduces ${want.correspondsTo} in its inner region`, () => {
      // **The depth-1 side is read from `EXPECTED`** — the hand-written table the
      // nine rows are asserted against — and NOT re-derived from a run. Sourcing
      // both sides from one run would make this assertion true by construction,
      // which is `doc/workflow.md` rule 8's third obligation in the one place
      // this file could fail it.
      //
      // **Measured, because the guard looks redundant and is not quite.** With
      // the source swapped to a run, breaking `live-token-requiring-arrival`'s
      // `unsatisfiable` clause costs **35** failures instead of **36**: the nine
      // rows catch the policy either way, and the one assertion that goes is this
      // pairing — the only place the depth-1 answer and the depth-2 answer are
      // compared to each other rather than each to the spec.
      const depth1 = EXPECTED[want.correspondsTo]!;
      for (const [key, id] of COLS) {
        const got = cells.find((c) => c.policyId === id)!.regions['inner']!;
        equal({ status: got.status, describe: rename(got.describe) },
          { status: depth1[key].status, describe: depth1[key].describe },
          `${scenario.key}/${id}: the inner region must answer exactly as ${want.correspondsTo} ` +
          'does at depth 1. A difference is a nesting-specific behaviour, which is precisely ' +
          'what ADR 0030 claims does not exist');
      }
    });
  }

  test('the depth-2 corpus is the SCENARIO list, and every row of it has an expectation', () => {
    // **BLOCKING, W22's adequacy reader**: deleting a whole row from
    // `NESTED_SCENARIOS` cost **0 failures** and six silent test cases. The only
    // guard read `NESTED_EXPECTED` — the expectation table — so a row that
    // vanished from the corpus took its own assertions with it and left the
    // count of expectations intact. The depth-1 suite has the mirror-image guard
    // (`BY_KEY.size === SCENARIOS.length * MATRIX_POLICY_IDS.length`); this had
    // none, and ADR 0030's evidence is "sixteen cells" with nothing counting to
    // sixteen.
    equal(NESTED_SCENARIOS.map((s) => s.key).sort(),
      Object.keys(NESTED_EXPECTED).sort(),
      'every declared depth-2 row has an expectation and every expectation has a row');
    equal(NESTED.length * COLS.length, 16,
      'sixteen cells, which is the number ADR 0030 states as its evidence. A row or a column ' +
      'that quietly left would take four of them and no failure with it');
  });

  test('and the four columns are the matrix four, not a private list', () => {
    // The other half of the same BLOCKING finding: `COLS` is what every depth-2
    // assertion loops over, and nothing compared it to the column list the render
    // and the depth-1 suite use.
    equal(COLS.map(([, id]) => id), [...MATRIX_POLICY_IDS],
      'the depth-2 suites must run every column the table advertises, in the same order');
    equal(COLS.map(([, id]) => id), MATRIX_COLUMNS.map((p) => p.id),
      'and the ids must be the policies actually run, so the two cannot drift either');
  });

  test('and the four rows cover four DISTINCT depth-1 rows', () => {
    const covered = Object.values(NESTED_EXPECTED).map((e) => e.correspondsTo).sort();
    equal(covered, ['all-arrive', 'all-exit', 'lost-settled', 'routed-away'],
      'one control plus the three terminal events. A row list that repeated a shape would ' +
      'report four rows of coverage and carry fewer');
    for (const key of covered) {
      ok(EXPECTED[key] !== undefined, `${key} must be one of the nine depth-1 rows`);
    }
  });

  test('the outer region is NOT claimed to correspond, and that is the finding', () => {
    // On three of four rows the outer join answers as a depth-1 join would. On
    // `nested-inner-all-exit` under the fourth column it does not: the inner join
    // is `unsatisfiable` and the outer one is `satisfied`, because W22's emission
    // ends the outer branch and `scoreA` had already arrived. **Transitivity is a
    // claim about a REGION, not about a row**, and this is the row that shows the
    // difference matters.
    const row = NESTED.find((r) => r.scenario.key === 'nested-inner-all-exit')!;
    const c = row.cells.find((x) => x.policyId === 'live-token-requiring-arrival')!;
    equal(c.regions['inner']!.status, 'unsatisfiable', 'the inner join can never fire');
    equal(c.regions['outer']!.status, 'satisfied', 'and the outer one fires anyway');
    equal(c.unsatisfiable.map((u) => u.fanoutId), ['inner'],
      'exactly one region is reported dead, and it is the inner one. Reporting the outer join ' +
      'too would be the driver deciding satisfaction, which section 4 gives to a policy');
  });
});

/**
 * **The depth-2 table is a deliverable, so it is asserted field by field too.**
 * `render.ts` prints it and no `package.json` script executes `render.ts`, which
 * is exactly the hole W15's adequacy reader found seven surviving mutations in.
 * Four rows shown to nobody would be that defect with the halves swapped
 * ([Q100](../../doc/open-questions.md)).
 */
suite('the depth-2 table renders, and the multi-region arm is executed', (test) => {
  const rows = nestedRows();
  const lines = renderNested().split('\n');

  test('same header and separator as the nine-row table — one renderer, one layout', () => {
    // **Two sources, and it took a reader to notice there was one.** `rows` and
    // `renderNested()` both call `nestedRows()`, so `lines.length === rows.length + 2`
    // is a tautology: truncating `nestedRows()` from the second row on cost **0**
    // failures, where the same edit to `matrixRows()` costs 1 because the depth-1
    // suite counts against `SCENARIOS`. The scenario list is the independent
    // source, so the count is taken from it.
    equal(lines.length, NESTED_SCENARIOS.length + 2,
      'header, rule, and one line per DECLARED row — counted from the scenario list, not from ' +
      'the same call that produced the render');
    equal(rows.length, NESTED_SCENARIOS.length,
      'and nestedRows() renders every declared row rather than a slice of them');
    equal(lines[0], `| row | ${MATRIX_POLICY_IDS.join(' | ')} |`, 'FOUR columns, named and in order');
    equal(lines[1], `|---|${MATRIX_POLICY_IDS.map(() => '---').join('|')}|`, 'and a separator per column');
  });

  test('the row carries the SHARED prefix, not column zero`s stream', () => {
    // The depth-1 renderer printed `cells[0].events` for the row. At depth 2 that
    // is `arrival-count`'s — the one column whose inner join never fires — so the
    // row would advertise the shortest stream of the four as though it were the
    // input. The prefix is computed from all four instead.
    for (const [i, { scenario, cells }] of rows.entries()) {
      const rowCell = lines[i + 2]!.split('|')[1]!;
      const streams = MATRIX_POLICY_IDS.map((id) => cells.find((c) => c.policyId === id)!.events);
      let n = 0;
      while (streams.every((s) => s.length > n && s[n] === streams[0]![n])) n++;
      ok(rowCell.includes(streams[0]!.slice(0, n).join(' ')),
        `${scenario.key}: the row does not carry the stream all four columns saw`);
      ok(rowCell.includes(`**${scenario.key}**`) && rowCell.includes(scenario.title),
        `${scenario.key}: the row must name itself and say what it is`);
      // **And no column's own tail leaks into the row label.** The assertion
      // above cannot catch that on its own: `arrival-count` is the strictest
      // policy, so any join it satisfies every other column satisfies too — which
      // makes its stream EXACTLY the common prefix on all four rows, and
      // `cells[0].events` therefore indistinguishable from the computed prefix
      // here. What is distinguishable is a column that fires where another does
      // not, so this names those events directly.
      for (const ev of ['arrived(outer:1)', 'lost(outer:1)']) {
        const shared = MATRIX_POLICY_IDS.every((id) =>
          cells.find((c) => c.policyId === id)!.events.includes(ev));
        if (!shared) {
          ok(!rowCell.includes(ev),
            `${scenario.key}: the row label carries "${ev}", which only SOME columns emit. The ` +
            'row is the input all four saw; a tail belongs in its own cell');
        }
      }
    }
  });

  test('every cell carries BOTH regions, in its own column, by position', () => {
    for (const [i, { scenario, cells }] of rows.entries()) {
      const fields = lines[i + 2]!.split('|');
      equal(fields.length, MATRIX_POLICY_IDS.length + 3,
        `${scenario.key}: ${fields.length - 3} cells, not ${MATRIX_POLICY_IDS.length}`);
      for (const [j, id] of MATRIX_POLICY_IDS.entries()) {
        const cell = fields[j + 2]!;
        const c = cells.find((x) => x.policyId === id)!;
        ok(cell.includes(`**${c.verdict}**`), `${scenario.key}: column ${j} (${id}) lacks its verdict`);
        for (const f of scenario.regions!) {
          ok(cell.includes(`${f} \`${c.regions[f]!.status}\` ${JSON.stringify(c.regions[f]!.describe)}`),
            `${scenario.key}: column ${j} (${id}) does not carry region "${f}". A depth-2 table ` +
            'showing one join is the defect `Cell.regions` was added to remove, printed');
        }
      }
    }
  });

  test('and each cell carries ITS OWN tail, which is how the four columns differ', () => {
    const row = rows.find((r) => r.scenario.key === 'nested-inner-all-exit')!;
    const fields = lines[rows.indexOf(row) + 2]!.split('|');
    const at = (id: string) => fields[MATRIX_POLICY_IDS.indexOf(id as never) + 2]!;
    ok(at('arrival-count').includes('then: `(nothing)`'),
      'arrival-count`s inner join never concludes, so the outer region sees nothing further');
    ok(at('live-token').includes('then: `arrived(outer:1)`'),
      'live-token fires the inner join, and that IS the outer branch arriving');
    ok(at('live-token-requiring-arrival').includes('then: `lost(outer:1)`'),
      'and the fourth column declares the inner join dead, which ends the outer branch — ' +
      'ADR 0030 rule 4, and the one event this item added');
  });

  test('the nine-row table is unchanged by all of this', () => {
    // The single-region arm must still print byte-for-byte what W15 built, or
    // ADR 0025's pasted table silently stops matching the renderer.
    const depth1 = renderMatrix().split('\n');
    const first = matrixRows()[0]!;
    const c = first.cells[0]!;
    ok(depth1[2]!.includes(`\`${c.status}\` / **${c.verdict}** <br> ${JSON.stringify(c.describe)}`),
      'a depth-1 cell still reads "`status` / **verdict** <br> describe", with no region prefix');
  });
});

/**
 * **What the two readers found the depth-2 suites were not saying** — W22, and
 * every one of these is an edit that cost 0 failures before it existed.
 */
suite('the depth-2 rows say what they declare — the readers` gaps', (test) => {
  test('every row`s `regions` is exactly its flow`s fanouts, outermost first', () => {
    // **W22's conformity reader (9) and adequacy reader (4, 6, 7).** `Scenario.regions`
    // is documented as *"every fanout in the flow, outermost first"* and nothing
    // compared it to the flow. Dropping `'inner'` from a row silently removed every
    // inner-region assertion for it; reversing the pair cost nothing either.
    for (const s of NESTED_SCENARIOS) {
      const fanouts = s.flow.nodes.filter((n) => n.kind === 'fanout').map((n) => n.id);
      equal([...(s.regions ?? [])].sort(), [...fanouts].sort(),
        `${s.key}: declares regions the flow does not have, or omits one it does`);
      // "Outermost first" is a claim about nesting, not about declaration order,
      // so it is derived from the graph: an outer fanout's own path is shorter
      // than an inner one's (`spec/task-id.md` section 1).
      const regions = allRegions(buildGraph(s.flow), s.flow);
      const depth = (id: string) => branchPathOf(regions, id).split('.').length - (branchPathOf(regions, id) === '-' ? 1 : 0);
      const depths = (s.regions ?? []).map(depth);
      equal(depths, [...depths].sort((a, b) => a - b),
        `${s.key}: regions are not outermost-first, which is the order the rendered cell prints`);
    }
  });

  test('a DEPTH-1 row`s Cell.regions is exactly its own fanout, and that default is asserted', () => {
    // **Adequacy reader (6).** `scenario.regions ?? [scenario.fanoutId]` runs on
    // every one of the nine depth-1 rows and nothing read it: changing the default
    // to `[]` cost 0. The field's declared contract is that depth 1 is unchanged
    // and this is additive, so depth 1 is where that is checked.
    for (const { scenario, cells } of ALL) {
      for (const c of cells) {
        equal(Object.keys(c.regions), [scenario.fanoutId],
          `${scenario.key}/${c.policyId}: a row that declares no regions reports exactly its own`);
        equal({ status: c.regions[scenario.fanoutId]!.status, describe: c.regions[scenario.fanoutId]!.describe },
          { status: c.status, describe: c.describe },
          `${scenario.key}/${c.policyId}: and it is the same answer Cell.status carries`);
      }
    }
  });

  test('the rendered cell prints the regions in the declared order', () => {
    // **Adequacy reader (4).** The cell assertions use `includes` per region, which
    // is order-blind — the same defect this file's own comment records for columns
    // (*"the reader transposed the cells against their own asserted header and
    // nothing noticed"*), one level in. Reversing the region list in the renderer
    // cost 0.
    const lines = renderNested().split('\n');
    for (const [i, { scenario, cells }] of nestedRows().entries()) {
      const fields = lines[i + 2]!.split('|');
      for (const [j, id] of MATRIX_POLICY_IDS.entries()) {
        const cell = fields[j + 2]!;
        const c = cells.find((x) => x.policyId === id)!;
        const at = scenario.regions!.map((f) =>
          cell.indexOf(`${f} \`${c.regions[f]!.status}\``));
        equal(at, [...at].sort((a, b) => a - b),
          `${scenario.key}/${id}: the cell prints its regions out of declared order, so a reader ` +
          'cannot tell the outer answer from the inner one by position');
      }
    }
  });

  test('JP-R2 and JP-R3 hold for the depth-2 cells too, not only the nine', () => {
    // **Adequacy reader (8).** Every *whole matrix* claim in this file iterates
    // `ALL`, which is `SCENARIOS`; the four depth-2 rows and their new
    // `Cell.regions[].describe` values were outside all of them.
    for (const { scenario, cells } of NESTED) {
      for (const c of cells) {
        for (const [f, r] of Object.entries(c.regions)) {
          ok(['waiting', 'satisfied', 'unsatisfiable'].includes(r.status),
            `${scenario.key}/${c.policyId}/${f}: JP-R3 — status is total, and "${r.status}" is not one of the three`);
          equal(JSON.parse(JSON.stringify(r.describe)), r.describe,
            `${scenario.key}/${c.policyId}/${f}: JP-R2 — describe must round-trip as JSON`);
        }
      }
    }
  });
});

/**
 * **Ladder L5 at a RUN-TIME arity — [P10](../../doc/plans/p10-is-fan-out-one-feature-or-two.md)'s
 * Scope item 4, and [W34](../../doc/work-items/w34-what-a-branch-receives-and-what-a-join-carries.md)'s
 * declared Output 3.**
 *
 * **Every cell below was derived by hand from `spec/join-policy.md` section 3's
 * four definitions and the row's own event stream, before it was run**, exactly as
 * the depth-1 nine were. The four definitions, so a reader can re-derive without
 * leaving this file:
 *
 *   `arrival-count`                 N is COUNTED from `branch.opened`; satisfied on
 *                                   N distinct arrivals with N at least one.
 *   `live-token`                    +1 opened, -1 arrived/exited/lost; satisfied at
 *                                   zero having been positive.
 *   `arrival-count-decrementing`    `arrival-count` plus `-1` on `branch.exited`,
 *                                   and **no `need > 0` pin** — `JP-R7`'s refused
 *                                   variant, kept executable so the refusal can be
 *                                   falsified (ADR 0025 rule 3).
 *   `live-token-requiring-arrival`  `live-token` plus at least one arrival, and
 *                                   `unsatisfiable` at zero-having-been-positive
 *                                   with none.
 *
 * **Prediction 3 is CONFIRMED: a map is a ROW question and not a column one.** A
 * column is a policy; a map is not. Nothing here adds or changes a column, and
 * `MATRIX_COLUMNS` is byte-unchanged.
 *
 * **What these rows can say that the other 52 cannot.** `arrival-count`'s `N` was
 * re-sourced from `region.branches.length` to `branch.opened` by W33, and **on
 * every static region the two agree** — which is why all 52 cells were unmoved by
 * that change and is exactly what made it a re-sourcing rather than a refinement.
 * A `map` region is the only input where they differ: `region.branches` is
 * `['score']`, length **1**, at every arity. So until these rows existed, L5 ran
 * the re-sourced policy only on inputs that could not tell it from the old one.
 */
suite('L5 at a run-time arity — the matrix over a `map` region', (test) => {
  const cellOfMap = (row: { cells: Cell[] }, id: string) => row.cells.find((c) => c.policyId === id)!;

  test('every map row answers what section 3`s four definitions say it should', () => {
    const expected: Record<string, Record<string, Answer>> = {
      // N = 3, every instance arrives. `arrival-count` needs the COUNTED 3 and gets
      // it; reading `branches.length` would give 1 and fire after one arrival.
      'map-all-arrive': {
        'arrival-count': { status: 'satisfied', describe: { need: 3, arrived: ['0', '1', '2'] }, verdict: 'joined' },
        'live-token': { status: 'satisfied', describe: { live: 0, positive: true }, verdict: 'joined' },
        'arrival-count-decrementing': { status: 'satisfied', describe: { need: 3, arrived: ['0', '1', '2'] }, verdict: 'joined' },
        'live-token-requiring-arrival': { status: 'satisfied', describe: { live: 0, positive: true, arrived: 3 }, verdict: 'joined' },
      },
      // P1's case at a run-time arity: three opened, one exited. `arrival-count`
      // hangs on 2 of 3 — its depth-1 behaviour at an arity nothing declared.
      'map-one-routed-away': {
        'arrival-count': { status: 'waiting', describe: { need: 3, arrived: ['0', '2'] }, verdict: 'stuck' },
        'live-token': { status: 'satisfied', describe: { live: 0, positive: true }, verdict: 'joined' },
        'arrival-count-decrementing': { status: 'satisfied', describe: { need: 2, arrived: ['0', '2'] }, verdict: 'joined' },
        'live-token-requiring-arrival': { status: 'satisfied', describe: { live: 0, positive: true, arrived: 2 }, verdict: 'joined' },
      },
      // Every instance exits: the all-exit row at a run-time arity. `JP-R7`'s
      // variant reaches `need: 0` with nothing arrived and FIRES — character for
      // character what ADR 0025 refused it for, now reachable from a map as well.
      'map-all-routed-away': {
        'arrival-count': { status: 'waiting', describe: { need: 2, arrived: [] }, verdict: 'stuck' },
        'live-token': { status: 'satisfied', describe: { live: 0, positive: true }, verdict: 'joined' },
        'arrival-count-decrementing': { status: 'satisfied', describe: { need: 0, arrived: [] }, verdict: 'joined' },
        'live-token-requiring-arrival': { status: 'unsatisfiable', describe: { live: 0, positive: true, arrived: 0 }, verdict: 'stuck' },
      },
      // A LOST instance, not an exited one — so `JP-R7`'s decrement does not apply
      // and its column hangs where the exited row fires. That difference is the
      // whole of `JP-R7`, seen at an arity nothing declared.
      'map-one-lost': {
        'arrival-count': { status: 'waiting', describe: { need: 2, arrived: ['0'] }, verdict: 'stuck' },
        'live-token': { status: 'satisfied', describe: { live: 0, positive: true }, verdict: 'joined' },
        'arrival-count-decrementing': { status: 'waiting', describe: { need: 2, arrived: ['0'] }, verdict: 'stuck' },
        'live-token-requiring-arrival': { status: 'satisfied', describe: { live: 0, positive: true, arrived: 1 }, verdict: 'joined' },
      },
      // N = 0 — no region event at all, so every policy is in its `open` state.
      // `FD-V9`'s floor makes this unreachable for a `fanout`.
      'map-zero-items': {
        'arrival-count': { status: 'waiting', describe: { need: 0, arrived: [] }, verdict: 'stuck' },
        'live-token': { status: 'waiting', describe: { live: 0, positive: false }, verdict: 'stuck' },
        'arrival-count-decrementing': { status: 'satisfied', describe: { need: 0, arrived: [] }, verdict: 'stuck' },
        'live-token-requiring-arrival': { status: 'waiting', describe: { live: 0, positive: false, arrived: 0 }, verdict: 'stuck' },
      },
    };

    let cells = 0;
    for (const { scenario, cells: cs } of MAP_ALL) {
      for (const c of cs) {
        cells++;
        const want = expected[scenario.key]![c.policyId]!;
        equal(c.status, want.status, `${scenario.key}/${c.policyId}: status`);
        equal(c.describe, want.describe, `${scenario.key}/${c.policyId}: describe`);
        equal(c.verdict, want.verdict, `${scenario.key}/${c.policyId}: verdict`);
      }
    }
    equal(cells, 20, 'five map rows x four columns = twenty cells, counted from what the loop DID');
    equal(Object.keys(expected).length, MAP_SCENARIOS.length,
      'and every declared row has an expectation — so adding a row without expecting it fails here ' +
      'rather than passing silently');
  });

  test('the map rows are what make `arrival-count`s re-sourced N a CLAIM rather than an identity', () => {
    // **The load-bearing cell, named rather than left inside the table above.** On
    // `map-all-arrive` the region's declared `branches` is `['score']` — length 1 —
    // and the correct `need` is 3. The two sources disagree here and NOWHERE ELSE
    // in the matrix, which is why W33's re-sourcing moved none of the other 52
    // cells and why this row had to exist for that change to be checked at L5 at
    // all.
    const row = MAP_ALL.find((r) => r.scenario.key === 'map-all-arrive')!;
    const ac = cellOfMap(row, 'arrival-count');
    equal((ac.describe as { need: number }).need, 3,
      '`need` is 3 — one per branch the region OPENED. Read from `region.branches.length` it is 1, ' +
      'and this join would fire after the FIRST arrival with two instances still running: a join ' +
      'routed out over an unfinished region, which is a failure direction W4`s matrix never saw ' +
      'because every failure it recorded was `need` too LARGE');
    equal(ac.events.filter((e) => e.startsWith('opened')).length, 3,
      'and three `branch.opened` events are what it counted — the source, asserted beside the value');
  });

  test('N = 0: `JP-R7`s variant says SATISFIED, and the driver does not ask it', () => {
    // **The sharpest cell in these five rows, and it is load-bearing for a decision
    // W33 measured as costing zero.** W33 removed `settleJoin` from the map arm's
    // N = 0 path, on the stated ground that *"no policy can answer anything but
    // `waiting` for a region that opened nothing"* — measured, and **true of the
    // three SHIPPED policies**, whose state after opening nothing is byte-identical
    // to their state before any branch opens.
    //
    // **It is false for `arrival-count-decrementing`**, which has no `need > 0` pin
    // — the pin `arrival-count` carries for exactly this reason — so `0 >= 0`
    // reports `satisfied` at `open`. This row is the first input in the repository
    // where that matters.
    //
    // **So the removal was right and its justification was stated wider than it was
    // measured** (`doc/workflow.md` section 1 rule 5's writing clause). Right,
    // because with the call restored this column would dispatch the join's successor
    // over a region **no branch ever reached** — character for character what
    // ADR 0025 refused `JP-R7`'s variant for. The scope is now written into
    // `spec/join-policy.md` section 5 beside the ruling.
    const row = MAP_ALL.find((r) => r.scenario.key === 'map-zero-items')!;
    const acd = cellOfMap(row, 'arrival-count-decrementing');
    equal(acd.status, 'satisfied',
      'a policy DOES answer satisfied at N = 0 — the refused variant, with no `need > 0` pin');
    equal(acd.joinFired, false,
      'and the join does NOT fire, because the driver never asks at N = 0. THIS is what the ' +
      'absent `settleJoin` call is worth, and it is worth zero on every other input');
    equal(acd.verdict, 'stuck', 'so the run is stuck, which is section 5`s ruling holding');
    for (const c of row.cells) {
      equal(c.joinFired, false, `${c.policyId}: no column fires a join at N = 0`);
      equal(c.events, [], `${c.policyId}: and no region event is emitted at all — the region is ` +
        'ENTERED, which only the fold can see');
    }
  });

  test('JP-R12 over a map region: the collection is keyed by ITEM INDEX, and absences are absent', () => {
    // The same rule as the depth-1 rows, at an arity nothing declared. Values come
    // from each row's own hand-written steps.
    const want: Record<string, Record<string, unknown>> = {
      'map-all-arrive': { '0': { from: 'item-0' }, '1': { from: 'item-1' }, '2': { from: 'item-2' } },
      'map-one-routed-away': { '0': { from: 'item-0' }, '2': { from: 'item-2' } },
      'map-all-routed-away': {},
      'map-one-lost': { '0': { from: 'item-0' } },
    };
    let checked = 0;
    for (const { scenario, cells } of MAP_ALL) {
      const w = want[scenario.key];
      if (w === undefined) continue; // map-zero-items fires no join at all
      for (const c of cells.filter((x) => x.joinFired)) {
        equal(c.payloads[scenario.downstream], w,
          `${scenario.key}/${c.policyId}: JP-R12 over a map region — one entry per ITEM that ` +
          'reached the join, keyed by its item index, and nothing for an item that exited or was ' +
          'lost');
        checked++;
      }
    }
    equal(checked, 11,
      'eleven firing map cells carry a collection. DERIVED per row: map-all-arrive 4 (every ' +
      'column); map-one-routed-away 3, arrival-count hanging on 2 of 3; map-all-routed-away 2, ' +
      'live-token and the decrementing variant firing over nothing while ' +
      'live-token-requiring-arrival declares it unsatisfiable; map-one-lost 2, the decrementing ' +
      'variant hanging because `lost` is not `exited`. 4 + 3 + 2 + 2 = 11');
  });
});

/**
 * **The map table renders, and it is asserted the way the depth-2 one is** —
 * [W34](../../doc/work-items/w34-what-a-branch-receives-and-what-a-join-carries.md).
 * `render.ts` is executed by no npm script, so a deliverable produced only there
 * is a deliverable nobody built ([Q100](../../doc/open-questions.md)); the whole
 * render is a function this suite imports, and these five rows join the twelve
 * that were already checked.
 */
suite('the run-time-arity table renders', (test) => {
  const rows = mapRows();
  const lines = renderMap().split('\n');

  test('same header and separator as the other two tables — one renderer, one layout', () => {
    // Counted from the SCENARIO list, not from the same call that produced the
    // render: `rows` and `renderMap()` both call `mapRows()`, so comparing them to
    // each other is a tautology. W22's reader's finding, inherited deliberately.
    equal(lines.length, MAP_SCENARIOS.length + 2,
      'header, rule, and one line per DECLARED map row — counted from the scenario list');
    equal(rows.length, MAP_SCENARIOS.length,
      'and mapRows() renders every declared row rather than a slice of them');
    equal(lines[0], `| row | ${MATRIX_POLICY_IDS.join(' | ')} |`, 'FOUR columns, named and in order');
    equal(lines[1], `|---|${MATRIX_POLICY_IDS.map(() => '---').join('|')}|`, 'and a separator per column');
  });

  test('every map row names itself, its stream, and each column`s own answer', () => {
    let ran = 0;
    for (const [i, { scenario, cells }] of rows.entries()) {
      ran++;
      const line = lines[i + 2]!;
      ok(line.includes(`**${scenario.key}**`) && line.includes(scenario.title),
        `${scenario.key}: the row must name itself and say what it is`);
      for (const c of cells) {
        ok(line.includes(JSON.stringify(c.describe)),
          `${scenario.key}/${c.policyId}: the cell must carry that column's own describe, so a ` +
          'render that printed one column four times would fail here');
      }
      // The N = 0 row's stream is EMPTY, and that is the fact worth showing: a
      // region entered that opened nothing emits no region event at all.
      if (scenario.key === 'map-zero-items') {
        ok(line.includes('<br> `` |'),
          'map-zero-items renders an empty event stream, which is what N = 0 looks like');
      }
    }
    equal(ran, 5, 'all five map rows rendered and checked — counted from what the loop DID');
  });
});
